#' Continuous Norming
#'
#' 
#' @param data the data as a data frame
#' @param raw the raw score variable in the data
#' @param group the explanatory or age/grouping variable in the data
#' @param weights an optional weighting variable specifying the weights of the
#'   single cases
#' @param method .
#' @param scale \code{'T'}, \code{'IQ'}, \code{'z'}, \code{'Wechsler'} (m =
#'   10, sd = 3), or \code{'PISA'} (m = 500, sd = 100)
#' @param descend .
#' @param nGroups .
#' @param equidistant .
#' @param k .
#' @param t .
#' @param selectionType .
#' @param terms .
#' @param alpha .
#' @param beta .
#' @param itemnumber .
#' @param muDegree .
#' @param sigmaDegree .
#' @param epsilonDegree .
#' @param deltaDegree .
#' @param fixDelta .
#' @param deltaValue .
#' @param cmpMuDegree .
#' @param cmpNuDegree .
#' @param cmpFixNu .
#' @param cmpNuValue .
#' @param cmpMaxScore .
#' @param model .
#' @param normAge .
#' @param range .
#' @param minRaw .
#' @param maxRaw .
#' @param stepping .
#' @param includeCI .
#' @param ciLevel .
#' @param reliability .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$modelFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelCoef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$norms} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$saveManifest} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveManifestPerc} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$savePredicted} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$savePredictedPerc} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelFit$asDF}
#'
#' \code{as.data.frame(results$modelFit)}
#'
#' @export
continuous <- function(
    data,
    raw,
    group,
    weights,
    method = "taylor",
    scale = "T",
    descend = FALSE,
    nGroups = 0,
    equidistant = FALSE,
    k = "5",
    t = "3",
    selectionType = "automaticSelection",
    terms = 4,
    alpha = "3",
    beta = "3",
    itemnumber = 0,
    muDegree = "3",
    sigmaDegree = "2",
    epsilonDegree = "2",
    deltaDegree = "1",
    fixDelta = FALSE,
    deltaValue = 1,
    cmpMuDegree = "3",
    cmpNuDegree = "2",
    cmpFixNu = FALSE,
    cmpNuValue = 1,
    cmpMaxScore = 0,
    model = TRUE,
    normAge = "",
    range = 3,
    minRaw = 0,
    maxRaw = 0,
    stepping = 1,
    includeCI = FALSE,
    ciLevel = 0.9,
    reliability = 0.9) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("continuous requires jmvcore to be installed (restart may be required)")

    if ( ! missing(raw)) raw <- jmvcore::resolveQuo(jmvcore::enquo(raw))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(raw), raw, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- continuousOptions$new(
        raw = raw,
        group = group,
        weights = weights,
        method = method,
        scale = scale,
        descend = descend,
        nGroups = nGroups,
        equidistant = equidistant,
        k = k,
        t = t,
        selectionType = selectionType,
        terms = terms,
        alpha = alpha,
        beta = beta,
        itemnumber = itemnumber,
        muDegree = muDegree,
        sigmaDegree = sigmaDegree,
        epsilonDegree = epsilonDegree,
        deltaDegree = deltaDegree,
        fixDelta = fixDelta,
        deltaValue = deltaValue,
        cmpMuDegree = cmpMuDegree,
        cmpNuDegree = cmpNuDegree,
        cmpFixNu = cmpFixNu,
        cmpNuValue = cmpNuValue,
        cmpMaxScore = cmpMaxScore,
        model = model,
        normAge = normAge,
        range = range,
        minRaw = minRaw,
        maxRaw = maxRaw,
        stepping = stepping,
        includeCI = includeCI,
        ciLevel = ciLevel,
        reliability = reliability)

    analysis <- continuousClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

